def tau_x_squared(x):
    """Calculates tau(x^2) given x."""
    if x <= 0:
        return 0

    # Factor x
    factors = {}
    n = x
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    # Calculate tau(x^2)
    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2a1) * p2^(2a2) * ...
    # tau(x^2) = (2a1 + 1)(2a2 + 1)...
    tau_x2 = 1
    for exponent in factors.values():
        tau_x2 *= (2 * exponent + 1)

    return tau_x2

